// @ts-check
/** @typedef {{kind:'card',number:string}|{kind:'transfer',iban:string}} Payment */

/** @param {Payment} p */
export function describe(p) {
  switch (p.kind) {
    case 'card':     return p.number;
    case 'transfer': return p.iban;
    default:         return assertNever(p);  // only checked under @ts-check
  }
}
